/**
 * Removes the leading and trailing blank lines of a template literal and the
 * indentation (tabs or spaces) shared by its non-blank lines.
 * @param {string} text The template literal text.
 * @returns {string} The text as it would be written at column 1.
 */
function dedent(text) {
	const lines = text
		.replace(/^\n/u, "")
		.replace(/\n\s*$/u, "")
		.split("\n");
	const indent = Math.min(
		...lines
			.filter(line => line.trim())
			.map(line => /^\s*/u.exec(line)[0].length),
	);

	return lines.map(line => line.slice(indent)).join("\n");
}

/**
 * Lints the given code with only `no-undef` enabled.
 * @param {string} code The code to lint.
 * @returns {Array<{line: number, column: number}>} The locations of the reported problems.
 */
function getNoUndefLocations(code) {
	return new Linter({ configType: "flat" })
		.verify(code, { rules: { "no-undef": "error" } })
		.map(({ line, column }) => ({ line, column }));
}

