	it("should report an undefined name on a later line at its column", () => {
		const code = dedent(`
			let x = 1;

			x = y;
		`);

		assert.deepStrictEqual(getNoUndefLocations(code), [
			{ line: 3, column: 5 },
		]);
	});

	it("should count the remaining nested indentation in the column", () => {
		const code = dedent(`
			const a = 1;
			function f() {
				return a + missing;
			}
		`);

		assert.deepStrictEqual(getNoUndefLocations(code), [
			{ line: 3, column: 13 },
		]);
	});
});
