/**
 * Removes the leading and trailing blank lines of a template literal and
 * strips the leading whitespace (tabs or spaces) shared by its non-blank lines.
 * @param {string[]} strings The strings in the template literal.
 * @param {any[]} values The interpolation values in the template literal.
 * @returns {string} The template literal without the shared indentation.
 */
function dedent(strings, ...values) {
	const lines = String.raw({ raw: strings }, ...values)
		.replace(/^[ \t]*\n/u, "")
		.replace(/\n[ \t]*$/u, "")
		.split("\n");
	const indents = lines
		.filter(line => line.trim())
		.map(line => line.match(/^[ \t]*/u)[0]);
	const shared = indents.reduce((prefix, indent) => {
		let i = 0;

		while (i < prefix.length && prefix[i] === indent[i]) {
			i++;
		}

		return prefix.slice(0, i);
	}, indents[0] ?? "");

	return lines
		.map(line => (line.startsWith(shared) ? line.slice(shared.length) : ""))
		.join("\n");
}

