/**
 * Removes the first and last lines of a template literal when they are blank,
 * then strips the leading whitespace shared by all non-blank lines.
 * @param {string} text The indented source text.
 * @returns {string} The source text without the shared indentation.
 */
function dedent(text) {
	const lines = text.split("\n");

	if (lines[0].trim() === "") {
		lines.shift();
	}
	if (lines.length > 0 && lines.at(-1).trim() === "") {
		lines.pop();
	}

	const indents = lines
		.filter(line => line.trim() !== "")
		.map(line => /^[\t ]*/u.exec(line)[0]);
	const common = indents.reduce((prefix, indent) => {
		let i = 0;

		while (i < prefix.length && prefix[i] === indent[i]) {
			i++;
		}
		return prefix.slice(0, i);
	}, indents[0] ?? "");

	return lines.map(line => line.slice(common.length)).join("\n");
}

